import os
import json
from abc import ABC, abstractmethod
from dataclasses import dataclass
from typing import Optional, List, Dict


@dataclass
class Message:
    """A single message in a conversation."""
    role: str  # 'system', 'user', or 'assistant'
    content: str


@dataclass
class AIResponse:
    """Standardized response from any AI provider."""
    content: str
    model: str
    provider: str
    input_tokens: int
    output_tokens: int
    cost_usd: float  # Estimated cost in USD


# ── Pricing table (per 1M tokens) ────────────────────────────────
PRICING = {
    "openai": {
        "gpt-4o-mini": {"input": 0.15, "output": 0.60},
        "gpt-4o": {"input": 2.50, "output": 10.00},
        "gpt-4.1": {"input": 2.00, "output": 8.00},
    },
    "anthropic": {
        "claude-haiku-3.5": {"input": 0.80, "output": 4.00},
        "claude-sonnet-4": {"input": 3.00, "output": 15.00},
        "claude-opus-4": {"input": 15.00, "output": 75.00},
    },
    "google": {
        "gemini-2.0-flash": {"input": 0.10, "output": 0.40},
        "gemini-2.5-pro": {"input": 1.25, "output": 10.00},
    },
    "xai": {
        "grok-3-mini": {"input": 0.30, "output": 0.50},
        "grok-3": {"input": 3.00, "output": 15.00},
    },
    "deepseek": {
        "deepseek-v3": {"input": 0.27, "output": 1.10},
        "deepseek-r1": {"input": 0.55, "output": 2.19},
    },
    "moonshot": {
        "kimi-k2": {"input": 0.60, "output": 2.40},
    },
}


def estimate_cost(provider: str, model: str,
                  input_tokens: int, output_tokens: int) -> float:
    """Estimate cost in USD for a given API call."""
    prices = PRICING.get(provider, {}).get(model)
    if not prices:
        return 0.0
    input_cost = (input_tokens / 1_000_000) * prices["input"]
    output_cost = (output_tokens / 1_000_000) * prices["output"]
    return round(input_cost + output_cost, 6)


# ── Base provider class ──────────────────────────────────────────
class BaseProvider(ABC):
    """Abstract base class for AI providers."""

    @abstractmethod
    def chat(self, messages: List[Message],
             model: str, temperature: float = 0.7) -> AIResponse:
        pass


# ── OpenAI ───────────────────────────────────────────────────────
class OpenAIProvider(BaseProvider):
    def __init__(self):
        from openai import OpenAI
        self.client = OpenAI(api_key=os.getenv("OPENAI_API_KEY"))

    def chat(self, messages, model="gpt-4o-mini", temperature=0.7):
        response = self.client.chat.completions.create(
            model=model,
            messages=[{"role": m.role, "content": m.content}
                      for m in messages],
            temperature=temperature,
        )
        usage = response.usage
        return AIResponse(
            content=response.choices[0].message.content,
            model=model, provider="openai",
            input_tokens=usage.prompt_tokens,
            output_tokens=usage.completion_tokens,
            cost_usd=estimate_cost(
                "openai", model,
                usage.prompt_tokens, usage.completion_tokens),
        )


# ── Anthropic ────────────────────────────────────────────────────
class AnthropicProvider(BaseProvider):
    def __init__(self):
        from anthropic import Anthropic
        self.client = Anthropic(api_key=os.getenv("ANTHROPIC_API_KEY"))

    def chat(self, messages, model="claude-sonnet-4-20250514",
             temperature=0.7):
        # Anthropic separates system from user/assistant messages
        system_msg = ""
        chat_msgs = []
        for m in messages:
            if m.role == "system":
                system_msg = m.content
            else:
                chat_msgs.append({"role": m.role, "content": m.content})

        response = self.client.messages.create(
            model=model,
            system=system_msg,
            messages=chat_msgs,
            max_tokens=2048,
            temperature=temperature,
        )
        return AIResponse(
            content=response.content[0].text,
            model=model, provider="anthropic",
            input_tokens=response.usage.input_tokens,
            output_tokens=response.usage.output_tokens,
            cost_usd=estimate_cost(
                "anthropic", "claude-sonnet-4",
                response.usage.input_tokens,
                response.usage.output_tokens),
        )


# ── Google Gemini ────────────────────────────────────────────────
class GoogleProvider(BaseProvider):
    def __init__(self):
        from google import genai
        self.client = genai.Client(
            api_key=os.getenv("GOOGLE_API_KEY"))

    def chat(self, messages, model="gemini-2.0-flash",
             temperature=0.7):
        # Build the prompt from messages
        prompt_parts = []
        for m in messages:
            prefix = f"[{m.role.upper()}]: "
            prompt_parts.append(prefix + m.content)
        prompt = "\n\n".join(prompt_parts)

        response = self.client.models.generate_content(
            model=model, contents=prompt,
            config={"temperature": temperature},
        )
        # Estimate tokens (Gemini returns usage metadata)
        input_tokens = response.usage_metadata.prompt_token_count or 0
        output_tokens = (
            response.usage_metadata.candidates_token_count or 0)
        return AIResponse(
            content=response.text,
            model=model, provider="google",
            input_tokens=input_tokens,
            output_tokens=output_tokens,
            cost_usd=estimate_cost(
                "google", model, input_tokens, output_tokens),
        )


