# ── Unified AIProvider ───────────────────────────────────────────
class AIProvider:
    """
    Unified interface for all AI providers.

    Usage:
        provider = AIProvider()  # reads AI_PROVIDER from .env
        response = provider.chat([
            Message('system', 'You are a helpful assistant.'),
            Message('user', 'Explain quantum computing.'),
        ])
        print(response.content)
        print(f'Cost: ${response.cost_usd:.4f}')
    """

    PROVIDERS = {
        "openai": OpenAIProvider,
        "anthropic": AnthropicProvider,
        "google": GoogleProvider,
        "xai": XAIProvider,
        "deepseek": DeepSeekProvider,
        "moonshot": MoonshotProvider,
    }

    def __init__(self, provider_name: Optional[str] = None):
        name = provider_name or os.getenv("AI_PROVIDER", "openai")
        if name not in self.PROVIDERS:
            raise ValueError(
                f"Unknown provider '{name}'. "
                f"Choose from: {list(self.PROVIDERS.keys())}")
        self.provider_name = name
        self._provider = self.PROVIDERS[name]()

    def chat(self, messages: List[Message],
             model: Optional[str] = None,
             temperature: float = 0.7) -> AIResponse:
        kwargs = {"messages": messages, "temperature": temperature}
        if model:
            kwargs["model"] = model
        return self._provider.chat(**kwargs)


# ── Example usage ────────────────────────────────────────────────
if __name__ == "__main__":
    # Switch provider by changing AI_PROVIDER in your .env:
    #   AI_PROVIDER=openai   -> uses OpenAI
    #   AI_PROVIDER=google   -> uses Gemini (free!)
    #   AI_PROVIDER=deepseek -> uses DeepSeek (cheapest paid)

    provider = AIProvider()  # defaults to AI_PROVIDER env var

    messages = [
        Message("system", "You are a helpful coding assistant."),
        Message("user", "Write a Python function to check "
                        "if a number is prime."),
    ]

    response = provider.chat(messages)

    print(f"Provider: {response.provider}")
    print(f"Model:    {response.model}")
    print(f"Tokens:   {response.input_tokens} in / "
          f"{response.output_tokens} out")
    print(f"Cost:     ${response.cost_usd:.6f}")
    print(f"\nResponse:\n{response.content}")

    # ── Compare costs across providers ───────────────────────
    print("\n" + "=" * 50)
    print("Cost comparison for 1000 similar requests:")
    print("=" * 50)
    est_input = response.input_tokens * 1000
    est_output = response.output_tokens * 1000

    for prov_name, models in PRICING.items():
        for model_name, prices in models.items():
            cost = estimate_cost(
                prov_name, model_name, est_input, est_output)
            print(f"  {prov_name:10s} {model_name:20s} ${cost:.4f}")
